package com.nexttv;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import android.graphics.Rect;import org.json.*;import java.util.*;
/** Repeated real keys at boundaries: assertions use actual focused nodes, not selected decoration. */
public class FocusBoundaryInstrumentation extends SettingsAppearanceInstrumentation {
 void repeatStable(int key,String label,int count)throws Exception{for(int i=0;i<count;i++){key(key);if(!focus().equals(label))throw new IllegalStateException("Focus escaped at "+i+" from "+label+" to "+focus());}}
 void smallWheel(float pixels)throws Exception{MotionEvent.PointerProperties p=new MotionEvent.PointerProperties();p.id=0;p.toolType=MotionEvent.TOOL_TYPE_MOUSE;MotionEvent.PointerCoords c=new MotionEvent.PointerCoords();c.x=500;c.y=350;c.setAxisValue(MotionEvent.AXIS_VSCROLL,-pixels/(48f*activity.getResources().getDisplayMetrics().density));long t=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(t,t,MotionEvent.ACTION_SCROLL,1,new MotionEvent.PointerProperties[]{p},new MotionEvent.PointerCoords[]{c},0,0,1,1,0,0,InputDevice.SOURCE_MOUSE,0);getUiAutomation().injectInputEvent(e,true);e.recycle();SystemClock.sleep(400);}
 AccessibilityNodeInfo fact(String prefix,AccessibilityNodeInfo n){if(n==null||!n.refresh())return null;if(n.getContentDescription()!=null&&n.getContentDescription().toString().startsWith(prefix))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=fact(prefix,n.getChild(i));if(r!=null)return r;}return null;}
 void sameFactHeights()throws Exception{int first=-1;List<Integer> heights=new ArrayList<>();for(String p:new String[]{"线路 ","分辨率 ","声道 ","接收速率 "}){AccessibilityNodeInfo n=fact(p,root());if(n==null)throw new IllegalStateException("Missing fact "+p);Rect b=new Rect();n.getBoundsInScreen(b);heights.add(b.height());if(first<0)first=b.height();if(Math.abs(first-b.height())>1)throw new IllegalStateException("Unequal fact heights "+heights);}pass("all four playback facts have equal actual layout height: "+heights);}
 @Override public void onStart(){int code=Activity.RESULT_OK;String result="";try{
  prefs=getTargetContext().getSharedPreferences("nexttv",0);saved=prefs.getAll();prefs.edit().putBoolean("start_live",false).putBoolean("grid_mode",true).putBoolean("channel_previews",false).putBoolean("reduce_motion",false).putBoolean("auto_update",false).putBoolean("auto_update_epg",false).commit();
  activity=startActivitySync(new Intent().setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await("home",()->focus().equals("频道"));home();key(KeyEvent.KEYCODE_DPAD_CENTER);await("group chooser",()->focus().contains("全部频道"));String first=focus();repeatStable(KeyEvent.KEYCODE_DPAD_UP,first,20);for(int i=0;i<40;i++){key(KeyEvent.KEYCODE_DPAD_DOWN);if(focus().isBlank())throw new IllegalStateException("Group focus disappeared");}String last=focus();repeatStable(KeyEvent.KEYCODE_DPAD_DOWN,last,10);key(KeyEvent.KEYCODE_ESCAPE);await("filter restored",()->focus().equals("分类"));pass("home group chooser stays on visible first/last choices after repeated Up/Down; no hidden anchor");
  smallWheel(1);if(grid().optInt("first")!=0||grid().optInt("offset")>2)throw new IllegalStateException("Unexpected one-pixel fixture "+grid());key(KeyEvent.KEYCODE_DPAD_DOWN);await("first row after fractional offset",()->grid().optInt("selectedIndex")==0);key(KeyEvent.KEYCODE_ESCAPE);home();
  long t=SystemClock.uptimeMillis();runOnMainSync(()->{for(int i=0;i<3;i++)activity.getWindow().getCallback().dispatchKeyEvent(new KeyEvent(t,t+i,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_DOWN,i));});SystemClock.sleep(250);if(grid().optInt("selectedIndex")!=0)throw new IllegalStateException("Queued repeats skipped first rendered row "+grid());runOnMainSync(()->activity.getWindow().getCallback().dispatchKeyEvent(new KeyEvent(t,t+300,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_DOWN,3)));await("hold continues after first frame",()->grid().optInt("selectedIndex")>=4);sendKeySync(new KeyEvent(t,SystemClock.uptimeMillis(),KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_DOWN,0));key(KeyEvent.KEYCODE_ESCAPE);pass("fractional top residual and same-frame held repeats enter first row, later held repeat continues scrolling");
  focusText("设置");key(KeyEvent.KEYCODE_DPAD_DOWN);
  for(String category:new String[]{"订阅与节目单","播放","频道与外观","高级","关于"}){focusText(category);key(KeyEvent.KEYCODE_DPAD_RIGHT);String start=focus();if(start.isBlank()||start.equals(category))throw new IllegalStateException("No content focus "+category);repeatStable(KeyEvent.KEYCODE_DPAD_UP,start,10);for(int i=0;i<12;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);String end=focus();repeatStable(KeyEvent.KEYCODE_DPAD_DOWN,end,8);key(KeyEvent.KEYCODE_DPAD_LEFT);await("Left restores category "+category,()->focus().equals(category));}
  pass("all five settings columns clamp first/last item while Left explicitly restores category");
  focusText("高级");key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_CENTER);await("network input",()->focus().contains("User-Agent"));String input=focus();repeatStable(KeyEvent.KEYCODE_DPAD_UP,input,8);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_DOWN);await("save",()->focus().equals("保存"));repeatStable(KeyEvent.KEYCODE_DPAD_DOWN,"保存",8);repeatStable(KeyEvent.KEYCODE_DPAD_RIGHT,"保存",8);key(KeyEvent.KEYCODE_TAB);await("Tab returns input",()->focus().contains("User-Agent"));if(ime())throw new IllegalStateException("Navigation opened IME");key(KeyEvent.KEYCODE_ESCAPE);pass("network fields/save and Tab stay inside editor without hidden focus or implicit keyboard");
  focusText("频道");click("CCTV1综合");rendered();key(KeyEvent.KEYCODE_INFO);sameFactHeights();shot("facts-aligned");key(KeyEvent.KEYCODE_MENU);await("quick action focused",()->!focus().isBlank());String quickFirst=focus();repeatStable(KeyEvent.KEYCODE_DPAD_UP,quickFirst,8);repeatStable(KeyEvent.KEYCODE_DPAD_LEFT,quickFirst,8);repeatStable(KeyEvent.KEYCODE_DPAD_DOWN,quickFirst,8);for(int i=0;i<15;i++)key(KeyEvent.KEYCODE_DPAD_RIGHT);await("last quick",()->focus().equals("主页"));repeatStable(KeyEvent.KEYCODE_DPAD_RIGHT,"主页",8);key(KeyEvent.KEYCODE_ESCAPE);pass("live quick controls clamp vertical and horizontal edges without losing playback focus");
  key(KeyEvent.KEYCODE_DPAD_CENTER);await("channel list",()->browser().optString("region").equals("channels"));key(KeyEvent.KEYCODE_DPAD_LEFT);await("group pane",()->browser().optString("region").equals("groups"));for(int i=0;i<40;i++)key(KeyEvent.KEYCODE_DPAD_UP);String group=focus();repeatStable(KeyEvent.KEYCODE_DPAD_UP,group,8);if(!browser().optString("region").equals("groups")||group.isBlank())throw new IllegalStateException("Group escaped");key(KeyEvent.KEYCODE_DPAD_RIGHT);await("channels only",()->browser().optString("pane").equals("channels"));for(int i=0;i<12;i++)key(KeyEvent.KEYCODE_DPAD_UP);String channel=focus();repeatStable(KeyEvent.KEYCODE_DPAD_UP,channel,8);if(channel.isBlank()||!browser().optString("region").equals("channels"))throw new IllegalStateException("Channel escaped");key(KeyEvent.KEYCODE_DPAD_RIGHT);await("programme pane",()->browser().optString("region").equals("epg"));for(int i=0;i<80;i++)key(KeyEvent.KEYCODE_DPAD_UP);String program=focus();repeatStable(KeyEvent.KEYCODE_DPAD_UP,program,8);key(KeyEvent.KEYCODE_DPAD_RIGHT);await("date pane",()->browser().optString("region").equals("dates"));for(int i=0;i<15;i++)key(KeyEvent.KEYCODE_DPAD_UP);String date=focus();repeatStable(KeyEvent.KEYCODE_DPAD_UP,date,8);for(int i=0;i<20;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);date=focus();repeatStable(KeyEvent.KEYCODE_DPAD_DOWN,date,8);key(KeyEvent.KEYCODE_ESCAPE);await("all panes closed",()->!dump().contains("NextTVBrowser"));pass("player groups/channels/programmes/dates clamp their own vertical edges and Back closes all panes");
  result="Global focus boundary "+passed+" groups passed";
 }catch(Throwable e){code=Activity.RESULT_CANCELED;result=android.util.Log.getStackTraceString(e)+"\n"+text()+"\n"+dump();try{shot("boundary-failure");}catch(Exception ignored){}}finally{restore();}Bundle b=new Bundle();b.putString("stream",result);finish(code,b);
 }
}
